import React, { useEffect, useState } from "react";
import axios from "axios";
import { useNavigate, useSearchParams } from 'react-router-dom';
import { MapContainer, TileLayer, CircleMarker, Popup, useMap, Tooltip } from 'react-leaflet';
import 'leaflet/dist/leaflet.css';
import "./RiverDashboard.css";

// ---------------------------------------------------------
// ⚙️ CONFIG & CONSTANTS
// ---------------------------------------------------------
const API_BASE_URL = process.env.NODE_ENV === 'production'
  ? 'https://aiiot-1.onrender.com'
  : 'http://localhost:8000';

const ITEMS_PER_PAGE = 6;

// 🎨 HELPER: Risk Color Logic (Dark Mode Optimized)
const getRiskStatus = (depth, isNormalState) => {
  if (isNormalState) {
    return {
      color: "#10b981", // Emerald
      bg: "rgba(16, 185, 129, 0.15)",
      label: "Safe Flow",
      icon: "fa-shield-check",
      glow: "0 0 15px rgba(16, 185, 129, 0.5)"
    };
  }
  if (depth <= 3) return { color: "#10b981", bg: "rgba(16, 185, 129, 0.15)", label: "Low Risk", icon: "fa-check-circle", glow: "0 0 10px rgba(16, 185, 129, 0.3)" };
  if (depth < 8) return { color: "#f59e0b", bg: "rgba(245, 158, 11, 0.15)", label: "Moderate", icon: "fa-exclamation-circle", glow: "0 0 15px rgba(245, 158, 11, 0.4)" };
  return { color: "#ef4444", bg: "rgba(239, 68, 68, 0.2)", label: "Critical", icon: "fa-radiation", glow: "0 0 20px rgba(239, 68, 68, 0.6)" };
};

// 🗺️ COMPONENT: Map View Controller
const MapController = ({ targetLoc }) => {
  const map = useMap();
  useEffect(() => {
    if (targetLoc) {
      map.flyTo(targetLoc, 14, { animate: true, duration: 1.5 });
    }
  }, [targetLoc, map]);
  return null;
};

// 🚀 MAIN COMPONENT
const FloodMap = () => {
  const navigate = useNavigate();
  const [searchParams] = useSearchParams();
  const [loading, setLoading] = useState(true);
  const [floodData, setFloodData] = useState(null);
  const [severePage, setSeverePage] = useState(1);
  const [mapCenter, setMapCenter] = useState([10.16, 76.43]);
  const [userPos, setUserPos] = useState(null);

  const simulatedLevel = searchParams.get('level');

  useEffect(() => {
    const fetchFloodAnalysis = async () => {
      try {
        setLoading(true);
        const response = await axios.get(`${API_BASE_URL}/api/weather/flood-analysis`, {
          params: { level: simulatedLevel }
        });
        if (response.data) {
          if (response.data.data) response.data.data.sort((a, b) => b.depth - a.depth);
          setFloodData(response.data);
        }
      } catch (error) {
        console.error("Hydrological data sync failed:", error);
      } finally {
        setLoading(false);
      }
    };
    fetchFloodAnalysis();
  }, [simulatedLevel]);

  const handleLocateUser = () => {
    if ("geolocation" in navigator) {
      navigator.geolocation.getCurrentPosition((pos) => {
        const coords = [pos.coords.latitude, pos.coords.longitude];
        setUserPos(coords);
        setMapCenter(coords);
      });
    }
  };

  if (loading) {
    return (
      <div className="rd-loading" style={{ background: '#0f172a', color: '#3b82f6' }}>
        <div className="rd-spinner" style={{ borderColor: '#3b82f6', borderTopColor: 'transparent' }}></div>
        <p style={{ letterSpacing: '2px', fontWeight: '800' }}>INITIALIZING GEOSPATIAL ENGINE...</p>
      </div>
    );
  }

  const threshold = floodData?.current_water_level || 3.5;
  const isNormalState = threshold <= 3.0;
  const severeZones = floodData?.data?.filter(d => d.depth >= threshold) || [];
  const totalPages = Math.ceil(severeZones.length / ITEMS_PER_PAGE);
  const currentSevere = severeZones.slice((severePage - 1) * ITEMS_PER_PAGE, severePage * ITEMS_PER_PAGE);

  return (
    <div style={{ position: 'relative', width: '100vw', height: '100vh', overflow: 'hidden', background: '#020617', fontFamily: "'Inter', sans-serif" }}>
      
      {/* 1. BACKGROUND LAYER: Full Screen Dark Map */}
      <div style={{ position: 'absolute', top: 0, left: 0, width: '100%', height: '100%', zIndex: 1 }}>
        <MapContainer 
          center={[10.16, 76.43]} 
          zoom={13} 
          zoomControl={false} 
          style={{ height: "100%", width: "100%", filter: 'grayscale(0.2) contrast(1.1)' }}
        >
          <TileLayer 
            url="https://{s}.basemaps.cartocdn.com/dark_all/{z}/{x}/{y}{r}.png" 
            attribution='&copy; OpenStreetMap &copy; CARTO'
          />
          <MapController targetLoc={mapCenter} />

          {/* User Location Pulse */}
          {userPos && (
            <CircleMarker 
              center={userPos} 
              radius={10} 
              pathOptions={{ color: '#3b82f6', fillColor: '#3b82f6', fillOpacity: 0.6, weight: 2 }}
            >
              <Popup><span style={{ fontWeight: '800' }}>CURRENT POSITION</span></Popup>
            </CircleMarker>
          )}

          {/* Flood Risk Points */}
          {floodData?.data?.map((point, idx) => {
            const status = getRiskStatus(point.depth, isNormalState);
            return (
              <CircleMarker
                key={idx} 
                center={[point.lat, point.lon]} 
                radius={8}
                pathOptions={{
                  color: status.color,
                  weight: 2,
                  fillColor: status.color,
                  fillOpacity: 0.4,
                }}
              >
                <Tooltip direction="top" offset={[0, -5]} opacity={0.9} sticky>
                  <div style={{ background: '#0f172a', color: '#fff', padding: '5px 10px', borderRadius: '4px', borderLeft: `3px solid ${status.color}` }}>
                    <strong style={{ display: 'block', fontSize: '12px' }}>{point.depth}m Inundation</strong>
                    <span style={{ fontSize: '10px', opacity: 0.7 }}>{status.label} Zone</span>
                  </div>
                </Tooltip>
              </CircleMarker>
            );
          })}
        </MapContainer>
      </div>

      {/* 2. TOP INTERFACE (HUD) */}
      <nav style={{
        position: 'absolute', top: '24px', left: '24px', right: '24px', zIndex: 10,
        display: 'flex', justifyContent: 'space-between', alignItems: 'center'
      }}>
        {/* Branding */}
        <div style={{
          background: 'rgba(15, 23, 42, 0.8)', backdropFilter: 'blur(16px)', padding: '12px 24px',
          borderRadius: '16px', border: '1px solid rgba(255,255,255,0.1)', color: 'white',
          display: 'flex', alignItems: 'center', gap: '16px', boxShadow: '0 8px 32px rgba(0,0,0,0.4)'
        }}>
          <div style={{ 
            background: 'linear-gradient(135deg, #3b82f6, #1d4ed8)', 
            width: '42px', height: '42px', borderRadius: '12px', 
            display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: '1.2rem'
          }}>
            <i className="fas fa-satellite-dish"></i>
          </div>
          <div>
            <h2 style={{ margin: 0, fontSize: '1.1rem', fontWeight: '900', letterSpacing: '1px' }}>PERIYAR GEOSPATIAL</h2>
            <div style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
              <span style={{ width: '8px', height: '8px', borderRadius: '50%', background: '#10b981', boxShadow: '0 0 10px #10b981' }}></span>
              <span style={{ fontSize: '0.65rem', opacity: 0.6, fontWeight: '700' }}>LIVE SENSOR SYNC</span>
            </div>
          </div>
        </div>

        {/* Global Actions */}
        <div style={{ display: 'flex', gap: '12px' }}>
          <button onClick={handleLocateUser} style={{
            background: 'rgba(15, 23, 42, 0.8)', color: '#3b82f6', border: '1px solid rgba(59, 130, 246, 0.3)',
            width: '48px', height: '48px', borderRadius: '14px', cursor: 'pointer', backdropFilter: 'blur(12px)', transition: '0.3s'
          }}>
            <i className="fas fa-location-crosshairs"></i>
          </button>
          <button onClick={() => navigate('/river-forecast')} style={{
            background: 'rgba(59, 130, 246, 0.2)', color: '#fff', border: '1px solid #3b82f6',
            padding: '0 24px', borderRadius: '14px', cursor: 'pointer', fontWeight: '700', 
            backdropFilter: 'blur(12px)', display: 'flex', alignItems: 'center', gap: '10px'
          }}>
            <i className="fas fa-chart-line"></i> SYSTEM DASHBOARD
          </button>
        </div>
      </nav>

      {/* 3. SIDE PANEL: Intelligence Report */}
      <aside style={{
        position: 'absolute', left: '24px', top: '110px', bottom: '100px', width: '380px',
        zIndex: 10, display: 'flex', flexDirection: 'column', gap: '20px'
      }}>
        {/* Status Card */}
        <div style={{
          background: 'rgba(15, 23, 42, 0.85)', backdropFilter: 'blur(20px)', padding: '24px',
          borderRadius: '24px', border: '1px solid rgba(255,255,255,0.08)', color: 'white',
          boxShadow: '0 20px 50px rgba(0,0,0,0.5)'
        }}>
          <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: '20px' }}>
            <span style={{ fontSize: '0.7rem', fontWeight: '800', opacity: 0.5, letterSpacing: '1.5px' }}>HYDROMETRIC LEVEL</span>
            <span style={{ fontSize: '0.7rem', fontWeight: '800', color: isNormalState ? '#10b981' : '#ef4444' }}>
              {isNormalState ? "STABLE" : "ALERT ACTIVE"}
            </span>
          </div>
          <div style={{ display: 'flex', alignItems: 'baseline', gap: '10px' }}>
            <h1 style={{ margin: 0, fontSize: '3.5rem', fontWeight: '900', lineHeight: 1 }}>{threshold}</h1>
            <span style={{ fontSize: '1.2rem', opacity: 0.4, fontWeight: '700' }}>m</span>
          </div>
          <div style={{ 
            marginTop: '20px', padding: '12px', background: isNormalState ? 'rgba(16, 185, 129, 0.1)' : 'rgba(239, 68, 68, 0.1)', 
            borderRadius: '12px', border: `1px solid ${isNormalState ? 'rgba(16, 185, 129, 0.2)' : 'rgba(239, 68, 68, 0.2)'}`,
            fontSize: '0.8rem', lineHeight: '1.4', color: isNormalState ? '#a7f3d0' : '#fecaca'
          }}>
            <i className={`fas ${isNormalState ? 'fa-circle-check' : 'fa-triangle-exclamation'}`} style={{ marginRight: '8px' }}></i>
            {isNormalState 
              ? "All watercourse readings are within seasonal safety parameters." 
              : `Water levels have exceeded the ${threshold}m warning threshold.`}
          </div>
        </div>

        {/* Impact List */}
        <div style={{
          background: 'rgba(15, 23, 42, 0.85)', backdropFilter: 'blur(20px)', padding: '24px',
          borderRadius: '24px', border: '1px solid rgba(255,255,255,0.08)', color: 'white',
          flex: 1, display: 'flex', flexDirection: 'column', overflow: 'hidden'
        }}>
          <h3 style={{ fontSize: '0.85rem', fontWeight: '800', marginBottom: '20px', letterSpacing: '1px', display: 'flex', alignItems: 'center', gap: '10px' }}>
            <i className="fas fa-map-location-dot" style={{ color: '#3b82f6' }}></i> HIGH-RISK SECTORS
          </h3>

          <div style={{ flex: 1, overflowY: 'auto', paddingRight: '8px' }} className="custom-scrollbar">
            {isNormalState ? (
              <div style={{ textAlign: 'center', padding: '60px 20px', opacity: 0.4 }}>
                <i className="fas fa-shield-halved" style={{ fontSize: '3rem', marginBottom: '15px' }}></i>
                <p style={{ fontSize: '0.9rem' }}>No critical inundation sectors detected in current simulation.</p>
              </div>
            ) : (
              currentSevere.map((item, idx) => {
                const status = getRiskStatus(item.depth, false);
                return (
                  <div key={idx} style={{
                    padding: '16px', background: 'rgba(255,255,255,0.03)', borderRadius: '16px',
                    marginBottom: '12px', borderLeft: `4px solid ${status.color}`, transition: '0.3s'
                  }}>
                    <div style={{ fontWeight: '800', fontSize: '0.95rem', marginBottom: '4px' }}>{item.place || `Zone ${idx + 1}`}</div>
                    <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                      <span style={{ fontSize: '0.75rem', opacity: 0.6 }}>Est. Depth: <b style={{ color: status.color }}>{item.depth}m</b></span>
                      <span style={{ fontSize: '0.65rem', fontWeight: '900', color: status.color, textTransform: 'uppercase' }}>{status.label}</span>
                    </div>
                  </div>
                );
              })
            )}
          </div>

          {/* Pagination */}
          {!isNormalState && totalPages > 1 && (
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginTop: '15px', paddingTop: '15px', borderTop: '1px solid rgba(255,255,255,0.05)' }}>
              <button 
                onClick={() => setSeverePage(p => Math.max(1, p - 1))} 
                disabled={severePage === 1}
                style={{ background: 'none', border: 'none', color: severePage === 1 ? '#334155' : '#3b82f6', cursor: 'pointer', fontWeight: '800', fontSize: '0.7rem' }}
              >
                PREVIOUS
              </button>
              <span style={{ fontSize: '0.75rem', fontWeight: '800', opacity: 0.5 }}>{severePage} / {totalPages}</span>
              <button 
                onClick={() => setSeverePage(p => Math.min(totalPages, p + 1))} 
                disabled={severePage === totalPages}
                style={{ background: 'none', border: 'none', color: severePage === totalPages ? '#334155' : '#3b82f6', cursor: 'pointer', fontWeight: '800', fontSize: '0.7rem' }}
              >
                NEXT
              </button>
            </div>
          )}
        </div>
      </aside>

      {/* 4. BOTTOM DOCK (Branding) */}
      <footer style={{
        position: 'absolute', bottom: '24px', left: '24px', right: '24px', zIndex: 10,
        background: 'rgba(15, 23, 42, 0.8)', backdropFilter: 'blur(16px)', padding: '12px 30px',
        borderRadius: '20px', border: '1px solid rgba(255,255,255,0.1)', color: 'white',
        display: 'flex', justifyContent: 'space-between', alignItems: 'center', boxShadow: '0 -10px 40px rgba(0,0,0,0.3)'
      }}>
        <div style={{ fontSize: '0.75rem', fontWeight: '700', letterSpacing: '0.5px' }}>
          <span style={{ color: '#3b82f6' }}>ADI SHANKARA</span> INSTITUTE OF ENGINEERING & TECHNOLOGY
        </div>
        <div style={{ display: 'flex', gap: '24px', fontSize: '0.65rem', fontWeight: '800', opacity: 0.5 }}>
          <span>KERALA, INDIA</span>
          <span>LAT: 10.1633 | LON: 76.4323</span>
          <span>© {new Date().getFullYear()} AI-IOT LABS</span>
        </div>
      </footer>

      {/* CSS Overrides for scrollbar and animations */}
      <style>{`
        .custom-scrollbar::-webkit-scrollbar { width: 4px; }
        .custom-scrollbar::-webkit-scrollbar-track { background: transparent; }
        .custom-scrollbar::-webkit-scrollbar-thumb { background: rgba(59, 130, 246, 0.3); border-radius: 10px; }
        .rd-loading { display: flex; flex-direction: column; align-items: center; justify-content: center; height: 100vh; gap: 20px; }
        .rd-spinner { width: 40px; height: 40px; border: 4px solid; border-radius: 50%; animation: spin 1s linear infinite; }
        @keyframes spin { 100% { transform: rotate(360deg); } }
      `}</style>
    </div>
  );
};

export default FloodMap;
